select.where:
d.release_plan_id = #{releasePlanId}

    and

        d.module_id = #{mId}


 and d.project_id = #{defect.projectId}
 and d.defect_type = #{defect.defectType, typeHandler=com.cat2bug.common.core.domain.handle.SysDefectTypeEnumTypeHandler }

    and (
        d.defect_name like concat('%', #{defect.nameVersionKeyword}, '%')
        or d.defect_name = #{defect.nameVersionKeyword}
        or d.project_num like concat('%', #{defect.nameVersionKeyword}, '%')
        or (d.module_version is not null and d.module_version like concat('%', #{defect.nameVersionKeyword}, '%'))
        or (m.module_name is not null and m.module_name like concat('%', #{defect.nameVersionKeyword}, '%'))
    )

 and d.defect_state = #{defect.defectState, typeHandler=com.cat2bug.common.core.domain.handle.SysDefectStateEnumTypeHandler}
 and d.defect_level = #{defect.defectLevel}
 and

        d.handle_by REGEXP CONCAT('\b',#{b},'\b') OR d.handle_by REGEXP CONCAT('\\b',#{b},'\\b')

